  param :code, ->(value) { value.to_s.downcase.to_sym }

  def view_template
    if (flag = FLAGS[@code])
      svg(**mix({ xmlns: "http://www.w3.org/2000/svg", viewBox: "0 0 40 40", width: "1em", height: "1em", aria_hidden: "true", data: { slot: "country-flag", code: @code } }, @attributes.except(:class)),
        class: @attributes[:class]) { |s| s.raw(s.safe(flag)) }
    else
      span(**mix({ aria_hidden: "true", data: { slot: "country-flag", code: @code } }, @attributes.except(:class)),
        class: cn("bg-background-strong text-foreground inline-flex items-center justify-center rounded-[30%] text-[0.4em] font-semibold uppercase", override: @attributes[:class])) { @code.to_s }
    end
  end
